function rankTags(tags) {
    const distinct = [];
    for (const tag of tags)
        if (!distinct.includes(tag))
            distinct.push(tag);
    const countOf = (tag) => {
        let count = 0;
        for (const other of tags)
            if (other === tag)
                count++;
        return count;
    };
    return distinct.sort((a, b) => {
        const difference = countOf(b) - countOf(a);
        if (difference !== 0)
            return difference;
        return a < b ? -1 : a > b ? 1 : 0;
    });
}

function rankTags(tags) {
    const counts = new Map();
    for (const tag of tags)
        counts.set(tag, (counts.get(tag) ?? 0) + 1);
    return [...counts.keys()].sort((a, b) => {
        const difference = counts.get(b) - counts.get(a);
        if (difference !== 0)
            return difference;
        return a < b ? -1 : a > b ? 1 : 0;
    });
}
